import{_ as s,a0 as n,w as i,s as l,ao as d,I as p,x as e,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux有问必答：如何查看Linux上程序或进程用到的库 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何查看Linux上程序或进程用到的库 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何查看Linux上程序或进程用到的库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何查看Linux上程序或进程用到的库 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140807 Linux FAQs with Answers--How to check what libraries are used by a program or process on Linux","title":"Linux有问必答：如何查看Linux上程序或进程用到的库","tag":"201408","desc":""},"relativePath":"201408/20140807 Linux FAQs with Answers--How to check what libraries are used by a program or process on Linux.md","filePath":"[post].md"}'),u={name:"201408/20140807 Linux FAQs with Answers--How to check what libraries are used by a program or process on Linux.md"};function m(x,t,c,f,L,_){const r=n("Link");return i(),l("div",null,[t[11]||(t[11]=d(`<h1 id="linux有问必答-如何查看linux上程序或进程用到的库" tabindex="-1">Linux有问必答：如何查看Linux上程序或进程用到的库 <a class="header-anchor" href="#linux有问必答-如何查看linux上程序或进程用到的库" aria-label="Permalink to “Linux有问必答：如何查看Linux上程序或进程用到的库”">​</a></h1><blockquote><p><strong>问题</strong>：我想知道当我调用一个特定的可执行文件在运行时载入了哪些共享库。是否有方法可以明确Linux上可执行程序或运行进程的共享库依赖关系？</p></blockquote><h3 id="查看可执行程序的共享库依赖关系" tabindex="-1">查看可执行程序的共享库依赖关系 <a class="header-anchor" href="#查看可执行程序的共享库依赖关系" aria-label="Permalink to “查看可执行程序的共享库依赖关系”">​</a></h3><p>要找出某个特定可执行依赖的库，可以使用ldd命令。这个命令调用动态链接器去找到程序的库文件依赖关系。</p><pre><code>$ ldd /path/to/program
</code></pre><p><img src="https://farm4.staticflickr.com/3872/14846153231_195cfff0f0_z.jpg" alt=""></p><p>注意！并不推荐为任何不可信的第三方可执行程序运行ldd，因为某些版本的ldd可能会直接调用可执行程序来明确其库文件依赖关系，这样可能不安全。</p><p>取而代之的是用一个更安全的方式来显示一个未知应用程序二进制文件的库文件依赖，使用如下命令：</p><pre><code>$ objdump -p /path/to/program | grep NEEDED 
</code></pre><p><img src="https://farm6.staticflickr.com/5552/14849218545_e3b667e742_o.png" alt=""></p><p>###查看运行进程的共享库依赖关系###</p><p>如果你想要找出被一个运行中的进程载入的共享库，你可以使用pldd命令，它会显示出在运行时被载入一个进程里的所有共享对象。</p><pre><code>$ sudo pldd &lt;PID&gt;
</code></pre><p>注意你需要root权限去执行pldd命令。</p><p><img src="https://farm6.staticflickr.com/5570/14846775694_96a6b96592_z.jpg" alt=""></p><p>或者，也可以选择一个叫做pmap的命令行工具。它报告一个进程的内存映射，也能显示出运行进程的库文件依赖。</p><pre><code>$ sudo pmap &lt;PID&gt;
</code></pre><p><img src="https://farm4.staticflickr.com/3919/14848885042_7e5bee2684_z.jpg" alt=""></p><hr>`,19)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(r,{href:"http://ask.xmodulo.com/check-library-dependency-program-process-linux.html"},{default:a(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/check-library-dependency-program-process-linux.html",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("译者：",-1)),o(r,{href:"https://github.com/KayGuoWhu"},{default:a(()=>[...t[2]||(t[2]=[e("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),o(r,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const T=s(u,[["render",m]]);export{b as __pageData,T as default};
